using System;
using System.Collections.Generic;
using System.Globalization;
using System.Reflection;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.Json.Serialization;

namespace AdaptiveCards
{
    /// <summary>
    /// Helper class used to convert an AdaptiveCard to/from JSON.
    /// </summary>
    public class AdaptiveCardConverter : JsonConverter<AdaptiveCard>, ILogWarnings
    {
        /// <summary>
        /// A list of warnings generated by the converter.
        /// </summary>
        public List<AdaptiveWarning> Warnings { get; set; } = new List<AdaptiveWarning>();

        /// <summary>
        /// The <see cref="ParseContext"/> for element tracking.
        /// </summary>
        public ParseContext ParseContext { get; set; } = new ParseContext();

        /// <summary>
        /// Initializes a new instance for serialization.
        /// </summary>
        public AdaptiveCardConverter() { }

        /// <summary>
        /// Initializes a new instance for deserialization with shared state.
        /// </summary>
        public AdaptiveCardConverter(List<AdaptiveWarning> warnings, ParseContext parseContext)
        {
            Warnings = warnings ?? new List<AdaptiveWarning>();
            ParseContext = parseContext ?? new ParseContext();
        }

        /// <inheritdoc/>
        public override AdaptiveCard Read(ref Utf8JsonReader reader, Type typeToConvert, JsonSerializerOptions options)
        {
            // Use JsonDocument to handle trailing commas and comments
            var doc = JsonDocument.ParseValue(ref reader);
            var jObject = SafeJsonHelper.SafeCreateJsonObject(doc.RootElement);
            if (jObject == null)
            {
                throw new AdaptiveSerializationException("Expected a JSON object for AdaptiveCard");
            }

            if (jObject["type"]?.GetValue<string>() != AdaptiveCard.TypeName)
            {
                throw new AdaptiveSerializationException($"Property 'type' must be '{AdaptiveCard.TypeName}'");
            }

            // Version validation
            ValidateJsonVersion(jObject);

            var versionStr = jObject["version"]?.GetValue<string>();
            if (versionStr != null && new AdaptiveSchemaVersion(versionStr) > AdaptiveCard.KnownSchemaVersion)
            {
                return MakeFallbackTextCard(jObject);
            }

            // Deserialize with options that skip this converter to avoid recursion
            var card = jObject.Deserialize<AdaptiveCard>(GetOptionsWithoutCardConverter(options));
            card.Lang = ValidateLang(jObject["lang"]?.GetValue<string>());

            return card;
        }

        /// <inheritdoc/>
        public override void Write(Utf8JsonWriter writer, AdaptiveCard value, JsonSerializerOptions options)
        {
            JsonSerializer.Serialize(writer, value, typeof(AdaptiveCard), GetOptionsWithoutCardConverter(options));
        }

        private void ValidateJsonVersion(JsonObject jObject)
        {
            string exceptionMessage = "";
            var version = jObject["version"];

            if (version == null)
            {
                exceptionMessage = "Could not parse required key: version. It was not found.";
            }
            else if (version.GetValue<string>() == "")
            {
                exceptionMessage = "Property is required but was found empty: version";
            }

            if (!String.IsNullOrEmpty(exceptionMessage))
            {
                if (AdaptiveCard.OnDeserializingMissingVersion == null)
                {
                    throw new AdaptiveSerializationException(exceptionMessage);
                }
                else
                {
                    var overriddenVersion = AdaptiveCard.OnDeserializingMissingVersion();
                    jObject["version"] = overriddenVersion.ToString();
                }
            }
        }

        private string ValidateLang(string val)
        {
            if (!string.IsNullOrEmpty(val))
            {
                try
                {
                    if (val.Length == 2 || val.Length == 3)
                    {
                        new CultureInfo(val);
                    }
                    else
                    {
                        Warnings.Add(new AdaptiveWarning((int)AdaptiveWarning.WarningStatusCode.InvalidLanguage, "Invalid language identifier: " + val));
                    }
                }
                catch (CultureNotFoundException)
                {
                    Warnings.Add(new AdaptiveWarning((int)AdaptiveWarning.WarningStatusCode.InvalidLanguage, "Invalid language identifier: " + val));
                }
            }
            return val;
        }

        private AdaptiveCard MakeFallbackTextCard(JsonObject jObject)
        {
            string fallbackText = jObject["fallbackText"]?.GetValue<string>();
            string speak = jObject["speak"]?.GetValue<string>();
            string language = jObject["lang"]?.GetValue<string>();

            if (string.IsNullOrEmpty(fallbackText))
            {
                fallbackText = "We're sorry, this card couldn't be displayed";
            }
            if (string.IsNullOrEmpty(speak))
            {
                speak = fallbackText;
            }
            if (string.IsNullOrEmpty(language))
            {
                language = CultureInfo.CurrentCulture.TwoLetterISOLanguageName;
            }

            AdaptiveCard fallbackCard = new AdaptiveCard("1.0")
            {
                Speak = speak,
                Lang = language
            };
            fallbackCard.Body.Add(new AdaptiveTextBlock
            {
                Text = fallbackText
            });

            Warnings.Add(new AdaptiveWarning((int)AdaptiveWarning.WarningStatusCode.UnsupportedSchemaVersion, "Schema version is not supported"));

            return fallbackCard;
        }

        private JsonSerializerOptions GetOptionsWithoutCardConverter(JsonSerializerOptions options)
        {
            var newOptions = new JsonSerializerOptions
            {
                PropertyNamingPolicy = options.PropertyNamingPolicy,
                PropertyNameCaseInsensitive = options.PropertyNameCaseInsensitive,
                DefaultIgnoreCondition = options.DefaultIgnoreCondition,
                WriteIndented = options.WriteIndented,
                AllowTrailingCommas = options.AllowTrailingCommas,
                ReadCommentHandling = options.ReadCommentHandling
            };

            foreach (var c in options.Converters)
            {
                if (!(c is AdaptiveCardConverter))
                {
                    newOptions.Converters.Add(c);
                }
            }

            return newOptions;
        }
    }
}
